package com.ezc.aragenPR.webapp.persistance.dao;

import java.util.Date;
import java.util.List;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

import com.ezc.aragenPR.webapp.model.EzPriceRequestHeader;

public interface PriceRequestHeaderRepository extends JpaRepository<EzPriceRequestHeader, String> {

	@Query(nativeQuery = true,value="SELECT DISTINCT EPRH_DOC_ID,EPRH_CREATED_BY,FIRST_NAME,EPRH_CREATED_ON,EPRH_APPROVED_BY,EPRH_STATUS,EPRH_COND_TYPE,ERPH_VAL_AREA,ERPH_VAL_DESC,EPRI_LINE_NO,EPRI_SALES_ORG,EPRI_CUSTOMER,EPRI_MATERIAL,EPRI_BRAND,EPRI_PLANT,EPRI_DIST_CHNL,EPRI_MAIN_CHNL,EPRI_SUB_CHNL,EPRI_CUST_TYPE,EPRI_CHAIN_CODE,EPRI_PRD_TYPE,EPRI_DIST_CAT,EPRI_DIVISION,EPRI_SALES_OFF,EPRI_VALID_FROM,EPRI_VALID_TO,EPRI_VALUE,EPRI_MRP,EPRI_LP,EPRI_SUB_TOT,EPRI_COGS,EPRI_MAR_AFT_DIS,EPRI_MAR_BEF_DIS FROM EZC_PRICE_REQ_HEADER A LEFT JOIN EZC_USERS B ON A.EPRH_CREATED_BY=B.USER_ID LEFT JOIN EZC_PRICE_REQ_ITEMS C ON A.EPRH_DOC_ID=C.EPRI_DOC_ID WHERE A.EPRH_CREATED_BY IN (:userId) AND (A.EPRH_CREATED_ON >= :fromDate AND A.EPRH_CREATED_ON <= :toDate)")
	List<Object[]> getUserReport(List<String> userId,Date fromDate,Date toDate);
	@Query(nativeQuery = true,value="SELECT DISTINCT EPRH_DOC_ID,EPRH_CREATED_BY,FIRST_NAME,EPRH_CREATED_ON,EPRH_APPROVED_BY,EPRH_STATUS,EPRH_COND_TYPE,ERPH_VAL_AREA,ERPH_VAL_DESC,EPRI_LINE_NO,EPRI_SALES_ORG,EPRI_CUSTOMER,EPRI_MATERIAL,EPRI_BRAND,EPRI_PLANT,EPRI_DIST_CHNL,EPRI_MAIN_CHNL,EPRI_SUB_CHNL,EPRI_CUST_TYPE,EPRI_CHAIN_CODE,EPRI_PRD_TYPE,EPRI_DIST_CAT,EPRI_DIVISION,EPRI_SALES_OFF,EPRI_VALID_FROM,EPRI_VALID_TO,EPRI_VALUE,EPRI_MRP,EPRI_LP,EPRI_SUB_TOT,EPRI_COGS,EPRI_MAR_AFT_DIS,EPRI_MAR_BEF_DIS FROM EZC_PRICE_REQ_HEADER A LEFT JOIN EZC_USERS B ON A.EPRH_CREATED_BY=B.USER_ID LEFT JOIN EZC_PRICE_REQ_ITEMS C ON A.EPRH_DOC_ID=C.EPRI_DOC_ID WHERE (A.EPRH_CREATED_ON >= :fromDate AND A.EPRH_CREATED_ON <= :toDate)")
	List<Object[]> getReport(Date fromDate,Date toDate);
	@Query(nativeQuery = true,value="SELECT DISTINCT EPRH_DOC_ID,EPRH_CREATED_BY,FIRST_NAME,EPRH_CREATED_ON,EPRH_APPROVED_BY,EPRH_STATUS,EPRH_COND_TYPE,ERPH_VAL_AREA,ERPH_VAL_DESC,EPRI_LINE_NO,EPRI_SALES_ORG,EPRI_CUSTOMER,EPRI_MATERIAL,EPRI_BRAND,EPRI_PLANT,EPRI_DIST_CHNL,EPRI_MAIN_CHNL,EPRI_SUB_CHNL,EPRI_CUST_TYPE,EPRI_CHAIN_CODE,EPRI_PRD_TYPE,EPRI_DIST_CAT,EPRI_DIVISION,EPRI_SALES_OFF,EPRI_VALID_FROM,EPRI_VALID_TO,EPRI_VALUE,EPRI_MRP,EPRI_LP,EPRI_SUB_TOT,EPRI_COGS,EPRI_MAR_AFT_DIS,EPRI_MAR_BEF_DIS FROM EZC_PRICE_REQ_HEADER A LEFT JOIN EZC_USERS B ON A.EPRH_CREATED_BY=B.USER_ID LEFT JOIN EZC_PRICE_REQ_ITEMS C ON A.EPRH_DOC_ID=C.EPRI_DOC_ID WHERE A.EPRH_WF_KEY IN (select EWM_WF_KEY from ezc_workflow_mapping where EWM_USER_ID in (:userId)) AND (A.EPRH_CREATED_ON >= :fromDate AND A.EPRH_CREATED_ON <= :toDate)")
	List<Object[]> getReportByWFKey(List<String> userId,Date fromDate,Date toDate);
	
}
